"""Object storage contract (api-contracts-v1 §5). Keys are generated by the app; user filenames never become keys."""

import uuid
from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True)
class PresignedUpload:
    url: str
    method: str
    headers: dict[str, str]
    expires_in: int


@dataclass(frozen=True)
class ObjectInfo:
    key: str
    size: int
    content_type: str | None


class StorageAdapter(Protocol):
    def presign_put(self, key: str, *, content_type: str, size: int, expires_s: int) -> PresignedUpload: ...
    def presign_get(self, key: str, *, expires_s: int, filename: str | None = None) -> str: ...
    def head(self, key: str) -> ObjectInfo | None: ...
    def delete(self, key: str) -> None: ...


def source_key(project_id: uuid.UUID, source_id: uuid.UUID, ext: str) -> str:
    return f"projects/{project_id}/sources/{source_id}/{uuid.uuid4()}.{ext.lstrip('.').lower()}"


def asset_key(project_id: uuid.UUID, asset_id: uuid.UUID, ext: str) -> str:
    return f"projects/{project_id}/assets/{asset_id}/{uuid.uuid4()}.{ext.lstrip('.').lower()}"


def export_key(project_id: uuid.UUID, export_id: uuid.UUID, file_name: str) -> str:
    return f"projects/{project_id}/exports/{export_id}/{file_name}"
